from authoring_helpers import DraftBatch,formula
b=DraftBatch('W02-L10-GAP',2,'L10','Static forces and velocity propagation',326,'robotics-integration-L10-gapfill-author')
b.add([333,334],'base-jacobian','General base-coordinate Jacobian','For x=L1 cosθ1+L2 cos(θ1+θ2) and y=L1 sinθ1+L2 sin(θ1+θ2), which base-frame position Jacobian is correct?', ['[[-L1 sinθ1-L2 sin(θ1+θ2), -L2 sin(θ1+θ2)], [L1 cosθ1+L2 cos(θ1+θ2), L2 cos(θ1+θ2)]]','[[-L1 sinθ1, -L2 sin(θ1+θ2)], [L1 cosθ1, L2 cos(θ1+θ2)]]','[[L1 sinθ1+L2 sin(θ1+θ2), L2 sin(θ1+θ2)], [L1 cosθ1+L2 cos(θ1+θ2), L2 cos(θ1+θ2)]]','[[-L1 sinθ1-L2 sinθ2, -L2 sinθ2], [L1 cosθ1+L2 cosθ2, L2 cosθ2]]'],0,'Differentiate each position component with respect to each joint angle; θ1 rotates both links, whereas θ2 affects only the second link.', ['Both columns include their correct partial derivatives.','The first column omits the second link’s motion under θ1.','The derivatives of cosine require negative sine in the first row.','The second link has absolute angle θ1+θ2, not θ2 alone.'],typ='derivation',steps=['Differentiate x and y with respect to θ1 for column 1.','Differentiate x and y with respect to θ2 for column 2.'],formulas=[formula('J=∂(x,y)/∂(θ1,θ2)',{'J':'base-coordinate planar position Jacobian','x,y':'tip position','L1,L2':'link lengths','θ1,θ2':'relative joint angles'},{'x,y,L1,L2':'m','θ1,θ2':'rad','J':'m/rad'})])
b.add(337,'full-inverse-command','Both inverse-Jacobian columns','Let L1=L2=1 m, θ1=30°, θ2=60° and the base-frame command (vx,vy)=(1,2) m/s; what joint rates solve J qdot=(vx,vy)?', ['(4/√3, -1-2√3) rad/s','(0, -1) rad/s','(4/√3, -1+2√3) rad/s','(2, -3) rad/s'],0,'At these angles J=[[-3/2,-1],[√3/2,0]]; the second row gives q1dot=4/√3 and the first gives q2dot=-1-2√3.', ['Substitution gives x velocity 1 m/s and y velocity 2 m/s.','This solves only the vx command and drops vy.','This reverses the inherited coupling sign.','This treats the y coefficient as 1 rather than √3/2.'],typ='numerical')
# Add explicit numerical working and formula metadata before the author freeze.
q=b.questions[-1]
next(o for o in q['options'] if o['id']=='o1')['text']='(4/√3, -1-2√3) rad/s'
next(o for o in q['options'] if o['id']=='o3')['text']='(4/√3, -1+2√3) rad/s'
why='J=[[-3/2,-1],[√3/2,0]] gives q1dot=4/√3 from the y row, then q2dot=-1-2√3 from the x row.'
q['solution']['justification']=q['solution']['simpleExplanation']=why;q['solution']['optionExplanations']['o1']='Substitution gives x velocity 1 m/s and y velocity 2 m/s.'
q['solution']['steps']=['Evaluate sin30°=1/2, cos30°=√3/2 and θ1+θ2=90°.','Solve (√3/2) q1dot=2.','Solve -(3/2) q1dot-q2dot=1.']
q['solution']['formulas']=[formula('qdot=J⁻¹[vx,vy]ᵀ',{'qdot':'joint-rate vector','J':'base-coordinate planar position Jacobian','vx,vy':'base-frame velocity components'},{'qdot':'rad/s','J':'m/rad','vx,vy':'m/s'},['L1=L2=1 m, θ1=30°, θ2=60°; sinθ2≠0.'])]
b.concepts[q['conceptIds'][0]]['description']=why;b.save()
b.add([346,347,348],'full-wrench-power','Force and moment contributions to power','At one reference point and in one coordinate basis, F=(2,-1,3) N, v=(0.5,2,-1) m/s, N=(1,4,-2) N·m and ω=(2,-0.5,1) rad/s; what is total instantaneous power?', ['-6 W','-4 W','-2 W','+6 W'],0,'Linear power is 1-2-3=-4 W and angular power is 2-2-2=-2 W; their sum is -6 W.', ['Both signed dot products are included.','This omits moment/angular-velocity power.','This includes only the angular part.','This reverses the sign of the specified wrench.'],typ='numerical',formulas=[formula('P=F·v+N·ω',{'P':'mechanical power','F':'force','v':'reference-point linear velocity','N':'moment about that reference point','ω':'angular velocity'},{'P':'W','F':'N','v':'m/s','N':'N·m','ω':'rad/s'},['All vectors share one basis; force/moment and velocity refer to the same point; wrench is exerted by the moving system.'])])
print(len(b.questions),'L10 gap drafts saved')

